if (!strcmp(name,"brow_right")) return brow_right;
if (!strcmp(name,"eye_left")) return eye_left;
if (!strcmp(name,"pupil_left")) return pupil_left;
if (!strcmp(name,"eye_right")) return eye_right;
if (!strcmp(name,"pupil_right")) return pupil_right;
